int data = 10;

// Base unqualified pointer
int* p_base = &data;

// T* to const T* (Implicit conversion: Adding qualification)
const int* p_const = p_base;

// T* to volatile T*
volatile int* p_volatile = p_base;

// const T* to const volatile T* (Adding more qualification)
const volatile int* p_cv = p_const;

// Demotion requires explicit const_cast
// int* p_error = p_const; // Error: Cannot implicitly remove const
int* p_demote = const_cast<int*>(p_const);
